/**
 * Live Instagram feed via the official Instagram API (graph.instagram.com, "Instagram API with Instagram Login").
 *
 * Requires a long-lived access token generated by the @indiehabitat account owner
 * (Professional — Business or Creator — account). See docs/deployment-guide.md → "Instagram feed".
 * The token lives in the database (Admin → Settings) or the INSTAGRAM_ACCESS_TOKEN env var, is never sent to the browser,
 * and is refreshed automatically before its 60-day expiry.
 *
 * Scraping instagram.com is deliberately NOT used: it breaks Instagram's terms and is blocked.
 */

export const INSTAGRAM_TAG = "instagram-feed";
export const INSTAGRAM_REVALIDATE_SECONDS = 3600;

export type InstagramMediaType = "IMAGE" | "VIDEO" | "CAROUSEL_ALBUM";

export type InstagramPost = {
  id: string;
  caption: string;
  mediaType: InstagramMediaType;
  image: string;
  permalink: string;
  timestamp: string;
};

type RawMedia = {
  id?: string;
  caption?: string;
  media_type?: string;
  media_url?: string;
  thumbnail_url?: string;
  permalink?: string;
  timestamp?: string;
};

const ALLOWED_IMAGE_HOST = /(^|\.)(cdninstagram\.com|fbcdn\.net)$/;

function safeUrl(u: string | undefined, hostCheck?: RegExp) {
  if (!u) return null;
  try {
    const url = new URL(u);
    if (url.protocol !== "https:") return null;
    if (hostCheck && !hostCheck.test(url.hostname)) return null;
    return url.toString();
  } catch {
    return null;
  }
}

/** Pure mapping from the Graph API response to post cards. Drops anything without a usable image or permalink. */
export function mapInstagramMedia(data: RawMedia[] | undefined, limit = 8): InstagramPost[] {
  const out: InstagramPost[] = [];
  for (const m of data ?? []) {
    const type = (["IMAGE", "VIDEO", "CAROUSEL_ALBUM"] as const).find((t) => t === m.media_type);
    if (!m.id || !type) continue;
    const image = safeUrl(type === "VIDEO" ? (m.thumbnail_url ?? m.media_url) : m.media_url, ALLOWED_IMAGE_HOST);
    const permalink = safeUrl(m.permalink);
    if (!image || !permalink || !/^https:\/\/(www\.)?instagram\.com\//.test(permalink)) continue;
    out.push({
      id: m.id,
      caption: (m.caption ?? "").trim(),
      mediaType: type,
      image,
      permalink,
      timestamp: m.timestamp ?? "",
    });
    if (out.length >= limit) break;
  }
  return out;
}

/** "2h ago", "3d ago", or a short date for anything older than a week. */
export function formatPostAge(iso: string, now = Date.now()) {
  const t = Date.parse(iso);
  if (Number.isNaN(t)) return "";
  const s = Math.max(0, Math.round((now - t) / 1000));
  if (s < 3600) return `${Math.max(1, Math.round(s / 60))}m ago`;
  if (s < 86400) return `${Math.round(s / 3600)}h ago`;
  if (s < 7 * 86400) return `${Math.round(s / 86400)}d ago`;
  return new Intl.DateTimeFormat("en-IN", { day: "numeric", month: "short", year: "numeric", timeZone: "Asia/Kolkata" }).format(t);
}

export function maskToken(token: string | null | undefined) {
  if (!token) return "";
  return token.length <= 10 ? "••••" : `${token.slice(0, 4)}••••••${token.slice(-4)}`;
}
